<?php
require_once __DIR__ . '/includes/auth.php'; require_login();
$pdo = db();
$total = (int)$pdo->query('SELECT COUNT(*) FROM solicitudes')->fetchColumn();
$today = (int)$pdo->query('SELECT COUNT(*) FROM solicitudes WHERE DATE(fecha_registro)=CURDATE()')->fetchColumn();
$points = (int)$pdo->query("SELECT COUNT(*) FROM puntos_atencion WHERE estado='activo'")->fetchColumn();
$recent = $pdo->query('SELECT s.id_solicitud,s.nombres,s.apellidos,s.barrio,s.fecha_registro,p.nombre AS punto FROM solicitudes s JOIN puntos_atencion p ON p.id_punto=s.id_punto ORDER BY s.fecha_registro DESC LIMIT 6')->fetchAll();
$pageTitle='Panel principal'; require __DIR__ . '/includes/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><div class="eyebrow">PANEL DE CONTROL</div><h1 class="page-title">Hola, <?= e(explode(' ', current_user()['name'])[0]) ?></h1><p class="text-secondary mb-0">Resumen general de la operación.</p></div><?php if (has_role(['administrador','ventanilla'])): ?><a href="nueva_solicitud.php" class="btn btn-primary">+ Registrar solicitud</a><?php endif; ?></div>
